// Generates typed protocol bindings for TypeScript and Rust from protocol/schema.json.
// Usage: node protocol/gen.mjs [--check]   (--check fails if generated files are stale)
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const schema = JSON.parse(readFileSync(join(here, "schema.json"), "utf8"));
const HEADER = "GENERATED by protocol/gen.mjs from protocol/schema.json. Do not edit.";

const pascal = (s) => s.split(/[^A-Za-z0-9]+/).filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");
const snake = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
const constName = (s) => s.replace(/[^A-Za-z0-9]+/g, "_").replace(/([a-z0-9])([A-Z])/g, "$1_$2").toUpperCase();

function tsType(t) {
  if (t.endsWith("[]")) return `${tsType(t.slice(0, -2))}[]`;
  return { string: "string", bool: "boolean", u32: "number", u64: "number", f64: "number", bytes: "string" }[t] ?? t;
}
function rsType(t) {
  if (t.endsWith("[]")) return `Vec<${rsType(t.slice(0, -2))}>`;
  return { string: "String", bool: "bool", u32: "u32", u64: "u64", f64: "f64", bytes: "String" }[t] ?? t;
}
function checkRef(t, where) {
  const base = t.replace(/\[\]$/, "");
  const prim = ["string", "bool", "u32", "u64", "f64", "bytes"];
  if (!prim.includes(base) && !(base in schema.types) && !(base in schema.enums)) {
    throw new Error(`unknown type ${t} in ${where}`);
  }
}

// ---------- TypeScript ----------
let ts = `// ${HEADER}\n/* eslint-disable */\n\nexport const PROTOCOL_VERSION = ${schema.version};\n\n`;
for (const [name, values] of Object.entries(schema.enums)) {
  ts += `export type ${name} = ${values.map((v) => JSON.stringify(v)).join(" | ")};\n`;
  ts += `export const ${name}Values: readonly ${name}[] = ${JSON.stringify(values)};\n\n`;
}
for (const [name, fields] of Object.entries(schema.types)) {
  ts += `export interface ${name} {\n`;
  for (const [rawField, type] of Object.entries(fields)) {
    checkRef(type, `${name}.${rawField}`);
    const opt = rawField.endsWith("?");
    const field = opt ? rawField.slice(0, -1) : rawField;
    ts += `  ${field}${opt ? "?" : ""}: ${tsType(type)};\n`;
  }
  ts += `}\n\n`;
}
ts += `export interface Requests {\n`;
for (const [method, { params, result }] of Object.entries(schema.requests)) {
  if (params) checkRef(params, method);
  if (result) checkRef(result, method);
  ts += `  ${JSON.stringify(method)}: { params: ${params ? tsType(params) : "null"}; result: ${result ? tsType(result) : "null"} };\n`;
}
ts += `}\n\nexport interface Notifications {\n`;
for (const [method, params] of Object.entries(schema.notifications)) {
  checkRef(params, method);
  ts += `  ${JSON.stringify(method)}: ${tsType(params)};\n`;
}
ts += `}\n\nexport type RequestMethod = keyof Requests;\nexport type NotificationMethod = keyof Notifications;\n`;

// ---------- Rust ----------
let rs = `// ${HEADER}\n#![allow(dead_code, clippy::all)]\n\nuse serde::{Deserialize, Serialize};\n\npub const PROTOCOL_VERSION: u32 = ${schema.version};\n\n`;
for (const [name, values] of Object.entries(schema.enums)) {
  rs += `#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]\npub enum ${name} {\n`;
  for (const v of values) rs += `    #[serde(rename = ${JSON.stringify(v)})]\n    ${pascal(v)},\n`;
  rs += `}\n\n`;
}
for (const [name, fields] of Object.entries(schema.types)) {
  rs += `#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]\n#[serde(rename_all = "camelCase")]\npub struct ${name} {\n`;
  for (const [rawField, type] of Object.entries(fields)) {
    const opt = rawField.endsWith("?");
    const field = opt ? rawField.slice(0, -1) : rawField;
    if (opt) rs += `    #[serde(default, skip_serializing_if = "Option::is_none")]\n    pub ${snake(field)}: Option<${rsType(type)}>,\n`;
    else rs += `    pub ${snake(field)}: ${rsType(type)},\n`;
  }
  rs += `}\n\n`;
}
rs += `pub mod method {\n`;
for (const m of Object.keys(schema.requests)) rs += `    pub const ${constName(m)}: &str = ${JSON.stringify(m)};\n`;
rs += `}\n\npub mod notification {\n`;
for (const m of Object.keys(schema.notifications)) rs += `    pub const ${constName(m)}: &str = ${JSON.stringify(m)};\n`;
rs += `}\n`;

const outputs = [
  [join(here, "generated", "protocol.ts"), ts],
  [join(here, "..", "indexer", "crates", "rpc", "src", "protocol.rs"), rs],
];
const check = process.argv.includes("--check");
let stale = false;
for (const [path, content] of outputs) {
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`stale: ${path}`);
      stale = true;
    }
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${path}`);
  }
}
if (stale) process.exit(1);
